class ImportInfo:
    """Represents a single import statement with POSIX path normalization."""
    module_name: str
    alias: Optional[str]
    is_from_import: bool
    level: int
    module_path: str = field(default_factory=str)

    def __post_init__(self):
        self.module_path = self._posix_path(self.module_name)

    def _posix_path(self, name: str) -> str:
        """Normalize module name to a POSIX-style path."""
        return PurePosixPath(name).as_posix()

